<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/products.php';
require_once __DIR__ . '/../includes/admin_layout.php';
require_admin();
$products = db()->query('SELECT p.*, c.name AS category_name FROM products p JOIN categories c ON c.id = p.category_id ORDER BY p.sort_order ASC, p.name ASC')->fetchAll();
$stats = ['products' => count($products), 'active' => count(array_filter($products, static fn(array $p): bool => (bool) $p['is_active'])), 'categories' => (int) db()->query('SELECT COUNT(*) FROM categories')->fetchColumn()];
admin_header('Products');
?><div class="stats-grid"><div class="stat-card"><span>Total products</span><strong><?= $stats['products'] ?></strong></div><div class="stat-card"><span>Visible in catalog</span><strong><?= $stats['active'] ?></strong></div><div class="stat-card"><span>Categories</span><strong><?= $stats['categories'] ?></strong></div></div><div class="admin-heading"><p class="section-note">Keep your collection current. Inactive pieces stay available here without appearing in the storefront.</p><a class="button button-dark" href="<?= e(app_url('admin/product_edit.php')) ?>">Add product +</a></div><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><strong><?= e($product['name']) ?></strong><br><small><?= e($product['slug']) ?></small></td><td><?= e($product['category_name']) ?></td><td><?= format_price($product['price'], $product['currency']) ?></td><td><?= $product['is_active'] ? 'Active' : 'Hidden' ?></td><td class="admin-actions"><a class="text-link" href="<?= e(app_url('admin/product_edit.php?id=' . $product['id'])) ?>">Edit</a><form method="post" action="<?= e(app_url('admin/product_delete.php')) ?>" onsubmit="return confirm('Delete this product?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($product['id']) ?>"><button class="text-link danger" style="background:none;border:0;font:inherit;padding:0">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php admin_footer(); ?>
